CREATE OR REPLACE VIEW `vwprovvigioni_fatturato` AS select `p`.`competenza` AS `competenza`,`p`.`denominazione_riferimento` AS `denominazione_riferimento`,`p`.`Provvigioni` AS `Provvigioni`,`f`.`fatturato` AS `fatturato`,(`p`.`Provvigioni` - `f`.`fatturato`) AS `delta` from (`vwprovvigioni` `p` left join `vwfatturepercompetenza` `f` on(((`p`.`fornitori_id` = `f`.`fornitori_id`) and (`p`.`competenza` = `f`.`competenza`)))) where ((`p`.`competenza` > 2024) and (`p`.`Provvigioni` > 0)) order by `p`.`competenza`,`p`.`denominazione_riferimento`
